static inline __sum16 csum_fold(__wsum sum) /* <=== csum_fold */ 
{
	u32 csum = (__force u32) sum;

	csum += (csum >> 16) + (csum << 16);
	csum >>= 16;
	return (__force __sum16) ~csum;
}

static void ip_cork_release(struct inet_cork *cork) /* <=== ip_cork_release */ 
{
	cork->flags &= ~IPCORK_OPT;
	kfree(cork->opt);
	cork->opt = NULL;
	dst_release(cork->dst);
	cork->dst = NULL;
}

static inline void sock_tx_timestamp(const struct sock *sk, __u16 tsflags, /* <=== sock_tx_timestamp */ 
				     __u8 *tx_flags)
{
